INSERT INTO `re_projects` (`id`, `name`, `content`, `images`, `location`, `number_block`, `number_floor`, `number_flat`, `is_featured`, `date_finish`, `date_sell`, `status`, `created_at`, `updated_at`, `investor_id`, `description`, `price_from`, `price_to`, `currency_id`, `city_id`, `author_id`, `author_type`, `latitude`, `longitude`, `views`, `country_id`, `state_id`, `unique_id`) VALUES
(5, 'Vista Verde', '<p>Vista Verde es un proyecto ecológico en Envigado, enfocado en la sostenibilidad. Los apartamentos están diseñados para aprovechar la luz natural y reducir el consumo de energía. Cuenta con áreas comunes ecoamigables, como huertos urbanos y puntos de reciclaje.</p><p><strong>Detalles</strong>:</p><ul><li><strong>Habitaciones</strong>: 1, 2 o 3</li><li><strong>Área Construida</strong>: 60 - 140 m²</li><li><strong>Amenidades</strong>: Huertos urbanos, puntos de reciclaje, senderos ecológicos</li></ul>', '{\"1\":\"propiedadesvip\\/2147764253.jpg\"}', 'Villa Hermosa', 5, 4, 125, 1, '2025-12-01', '2024-08-26', 'selling', '2019-11-18 03:45:06', '2024-08-26 01:43:54', 1, 'Innovador proyecto ecológico en Envigado', 80000, 150000, 1, 213, NULL, 'Botble\\ACL\\Models\\User', '6.255750161979436', '-75.55133364226447', 5630, 4, 33, NULL),
(6, 'Torres del Parque', '<p>Torres del Parque es un proyecto de apartamentos en El Poblado, diseñado para ofrecer comodidad y modernidad. Con opciones de 1, 2 y 3 habitaciones, cada torre cuenta con gimnasio, piscina y áreas verdes.</p><ul><li><strong>Detalles</strong>:<ul><li><strong>Habitaciones</strong>: 1, 2 o 3</li><li><strong>Área Construida</strong>: 70 - 150 m²</li><li><strong>Amenidades</strong>: Gimnasio, piscina, áreas verdes</li></ul></li></ul>', '{\"1\":\"propiedadesvip\\/2148252134.jpg\"}', 'Medellin', 10, 5, 540, 1, '2025-12-01', '2024-08-26', 'selling', '2019-11-18 03:53:20', '2024-08-26 01:51:12', 1, 'Proyecto de apartamentos en El Poblado con áreas sociales completas.', 100000, 200000, 1, 213, NULL, 'Botble\\ACL\\Models\\User', '6.248862601817405', '-75.56057200554429', 7129, 4, 33, NULL),
(13, 'Urban Life', '<p>Urban Life es un proyecto de apartamentos ubicado en el centro de Medellín, diseñado para profesionales jóvenes y estudiantes. Ofrece estudios y apartamentos de 1 habitación con acabados modernos y áreas comunes como coworking y gimnasio.</p><ul><li><strong>Detalles</strong>:<ul><li><strong>Habitaciones</strong>: Estudios y 1 habitación</li><li><strong>Área Construida</strong>: 40 - 80 m²</li><li><strong>Amenidades</strong>: Coworking, gimnasio, salón social</li></ul></li></ul>', '{\"1\":\"propiedadesvip\\/19907.jpg\"}', 'El poblado', 10, 8, 750, 1, '2025-08-29', '2024-08-26', 'selling', '2024-08-26 01:50:19', '2024-08-26 01:50:19', 1, 'Proyecto de apartamentos urbanos en el centro de Medellín.', 150000, 300000, 1, 213, NULL, 'Botble\\ACL\\Models\\User', '6.244629577147106', '-75.56519118718418', 58, 4, 33, NULL),
(14, 'La Colina', '<p>La Colina es un proyecto residencial en Las Palmas que ofrece apartamentos y casas con vistas panorámicas a Medellín. Con opciones de 2 a 4 habitaciones, cuenta con áreas verdes, piscina y un club social.</p><ul><li><strong>Detalles</strong>:<ul><li><strong>Habitaciones</strong>: 2, 3 o 4</li><li><strong>Área Construida</strong>: 80 - 200 m²</li><li><strong>Amenidades</strong>: Piscina, club social, áreas verdes</li></ul></li></ul>', '{\"1\":\"propiedadesvip\\/29879.jpg\",\"2\":\"13.jpg\",\"3\":\"11b.jpg\",\"4\":\"09.jpg\",\"5\":\"12.jpg\"}', 'Las Palmas', 5, 4, 25, 1, '2025-08-31', '2024-08-26', 'selling', '2024-08-26 01:56:55', '2024-10-18 14:03:21', 1, 'Proyecto residencial en la colina de Las Palmas', 75000, 120000, 1, 213, NULL, 'Botble\\ACL\\Models\\User', '6.245275295032132', '-75.57414085189912', 87, 4, 33, NULL);
INSERT INTO `re_projects_translations` (`lang_code`, `re_projects_id`, `name`, `description`, `content`, `location`) VALUES
('es_ES', 13, 'Urban Life', 'Proyecto de apartamentos urbanos en el centro de Medellín.', '<p>Urban Life es un proyecto de apartamentos ubicado en el centro de Medellín, diseñado para profesionales jóvenes y estudiantes. Ofrece estudios y apartamentos de 1 habitación con acabados modernos y áreas comunes como coworking y gimnasio.</p><ul><li><strong>Detalles</strong>:<ul><li><strong>Habitaciones</strong>: Estudios y 1 habitación</li><li><strong>Área Construida</strong>: 40 - 80 m²</li><li><strong>Amenidades</strong>: Coworking, gimnasio, salón social</li></ul></li></ul>', 'El poblado'),
('es_ES', 14, 'La Colina', 'Proyecto residencial en la colina de Las Palmas', '<p>La Colina es un proyecto residencial en Las Palmas que ofrece apartamentos y casas con vistas panorámicas a Medellín. Con opciones de 2 a 4 habitaciones, cuenta con áreas verdes, piscina y un club social.</p><ul><li><strong>Detalles</strong>:<ul><li><strong>Habitaciones</strong>: 2, 3 o 4</li><li><strong>Área Construida</strong>: 80 - 200 m²</li><li><strong>Amenidades</strong>: Piscina, club social, áreas verdes</li></ul></li></ul>', 'Las Palmas');
